import { readFile } from "fs/promises"
import path from "path"
import { NextResponse } from "next/server"

export async function POST(request: Request) {
  try {
    const body = await request.json()
    const { personaId, sessionId, userMessage, messages } = body

    // Determine the actual message to send (userMessage or last from messages)
    const currentMessage = userMessage || (messages && messages.length > 0 ? messages[messages.length - 1].content : "")

    if (!currentMessage) {
      return NextResponse.json(
        { error: "Missing userMessage" },
        { status: 400 }
      )
    }

    // Load Knowledge Base
    let knowledgeContext = ""
    let targetPersonaId = personaId || "impact_startups"

    // Safety check
    if (targetPersonaId.includes("..") || targetPersonaId.includes("/") || targetPersonaId.includes("\\")) {
      targetPersonaId = "impact_startups"
    }

    try {
      const knowledgePath = path.join(process.cwd(), "data", "knowledge", `${targetPersonaId}.md`)
      knowledgeContext = await readFile(knowledgePath, "utf-8")
    } catch (err) {
      console.warn(`Could not load knowledge for persona: ${targetPersonaId}, falling back to default.`)
      try {
        const defaultPath = path.join(process.cwd(), "data", "knowledge", "impact_startups.md")
        knowledgeContext = await readFile(defaultPath, "utf-8")
      } catch (fallbackErr) {
        knowledgeContext = ""
      }
    }

    const n8nUrl = process.env.N8N_WEBHOOK_URL || "https://lighteagle.app.n8n.cloud/webhook-test/weya-voice-chat"
    console.log("Calling n8n Webhook:", n8nUrl)

    if (!n8nUrl) {
      console.warn("N8N_WEBHOOK_URL is not set. Mocking response.")
      return NextResponse.json({
        assistantText: "System definition missing: N8N_WEBHOOK_URL is not set."
      })
    }

    // Forward to n8n
    const response = await fetch(n8nUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        personaId: targetPersonaId,
        sessionId,
        userMessage: currentMessage,
        knowledgeContext
      }),
    })

    if (!response.ok) {
      const errorText = await response.text()
      console.error(`n8n webhook failed with status: ${response.status}. Body: ${errorText}`)
      throw new Error(`n8n webhook failed with status: ${response.status}. Details: ${errorText}`)
    }

    const data = await response.json()

    // Normalize response
    // n8n might return [ { assistantText: "..." } ] or { assistantText: "..." }
    let assistantText = ""
    if (Array.isArray(data) && data.length > 0) {
      assistantText = data[0].assistantText || data[0].output || data[0].text
    } else {
      assistantText = data.assistantText || data.output || data.text
    }

    return NextResponse.json({
      assistantText: assistantText || "Received empty response from n8n."
    })

  } catch (error: any) {
    console.error("Error in chat route:", error)
    return NextResponse.json({ error: error.message || "Internal Server Error" }, { status: 500 })
  }
}
